  ]);
  const categories=q[0].rows[0].n,offers=q[1].rows[0].n,groups=q[2].rows[0].n,queues=q[3].rows[0].n;
  const marketplaces=q[4].rows[0].n,telegram=q[5].rows[0].n,whatsapp=q[6].rows[0].n,rules=q[7].rows[0].n;
