export const eligiblePublication = `
  EXISTS(SELECT 1 FROM accounts a WHERE a.id=p.account_id AND a.status='ACTIVE')
  AND o.status IN ('APPROVED','PUBLISHED')
  AND (p.scheduled_at IS NULL OR p.scheduled_at<=now())
