async function keyMaterial(){const raw=String(await config.get('CONNECTOR_ENCRYPTION_KEY')||'');if(raw.length<32)throw new Error('CONNECTOR_ENCRYPTION_KEY deve ter pelo menos 32 caracteres.');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw));return crypto.subtle.importKey('raw',digest,{name:'AES-GCM'},false,['encrypt','decrypt'])}
